constraint.cypher:
MATCH (e:Type:Entity)
    WHERE NOT e:Test AND NOT EXISTS { MATCH (e)-[:DECLARES]->(f:Field)-[:ANNOTATED_BY]->(:Annotation)-[:OF_TYPE]->(vt:Type) WHERE vt.fqn IN ['jakarta.persistence.Version', 'javax.persistence.Version'] }
    RETURN e AS Element, e.fqn AS Fqn, 'no @Version field' AS Detail
